// Token Launch Radar dashboard renderer (offline, zero network calls).
// Consumes window.RADAR_DATA generated by main.ts from the sealed snapshot.
(function () {
  "use strict";
  var data = window.RADAR_DATA || { rows: [], as_of: "", floor_usd: 0, stats: {} };
  var rows = Array.isArray(data.rows) ? data.rows : [];
  var stats = data.stats || {};
  var cv = stats.cv || {};

  var state = {
    q: "",
    segment: "all",
    cat: "all",
    chain: "all",
    verdict: "all",
    sort: "rank",
    activeSlug: null,
  };

  function $(id) { return document.getElementById(id); }
  function esc(s) {
    return String(s).replace(/[&<>"']/g, function (c) {
      if (c === "&") return "&amp;";
      if (c === "<") return "&lt;";
      if (c === ">") return "&gt;";
      if (c === '"') return "&quot;";
      return "&#39;";
    });
  }
  function fmtUsd(n) {
    if (n === null || n === undefined || !Number.isFinite(n)) return "n/a";
    if (n >= 1e9) return "$" + (n / 1e9).toFixed(2) + "B";
    if (n >= 1e6) return "$" + (n / 1e6).toFixed(1) + "M";
    if (n >= 1e3) return "$" + (n / 1e3).toFixed(0) + "K";
    return "$" + Math.round(n);
  }
  function fmtPct(n) {
    if (n === null || n === undefined || !Number.isFinite(n)) return "n/a";
    return (n > 0 ? "+" : "") + n.toFixed(1) + "%";
  }
  function fmtAge(days) {
    if (days === null || days === undefined) return "n/a";
    if (days < 30) return days + "d";
    if (days < 365) return Math.round(days / 30) + "mo";
    return (days / 365).toFixed(1) + "y";
  }
  function fmtMult(m) {
    return (m === null || m === undefined) ? "1.00x" : m.toFixed(2) + "x";
  }
  function growthCls(n) {
    if (n === null || n === undefined) return "flat";
    if (n > 1) return "pos";
    if (n < -1) return "neg";
    return "flat";
  }
  function verdictBadge(v) {
    if (v === "Watchlist Core") return '<span class="badge b-core">Watchlist Core</span>';
    if (v === "High-Conviction Farm") return '<span class="badge b-high">High Conviction</span>';
    if (v === "Asymmetric Early") return '<span class="badge b-early">Asymmetric</span>';
    return '<span class="badge b-mon">Monitor</span>';
  }

  function renderTopMeta() {
    $("meta").innerHTML =
      "<strong>Snapshot " + esc(data.as_of || "n/a") + " &middot; Floor " + fmtUsd(data.floor_usd || 50e6) + "</strong>" +
      rows.length + " pre-token ranked &middot; " + (stats.watchlist_covered || 0) + "/" + (stats.watchlist || 0) + " watchlist";
  }

  function renderStrip() {
    var totalImplied = rows.reduce(function (a, r) { return a + r.implied_value_usd; }, 0);
    $("strip").innerHTML =
      '<div class="card">' +
        '<div class="card-k">Snapshot Integrity Funnel</div>' +
        '<div class="card-v"><span class="hl-cyan">' + (stats.board_rows || rows.length) + '</span> / ' + (stats.total_snapshot || 0) + ' protocols</div>' +
        '<div class="card-sub">Excluded: ' + (stats.token_peers || 0) + ' peers, ' + (stats.traded_no_mcap || 0) + ' traded-no-mcap, ' + (stats.excluded_derivatives || 0) + ' deriv/CEX</div>' +
      '</div>' +
      '<div class="card">' +
        '<div class="card-k">5-Fold CV Conditional Fit</div>' +
        '<div class="card-v">R&sup2; <span class="hl-green">' + (cv.cv_r2 !== undefined ? cv.cv_r2.toFixed(2) : "n/a") + '</span> &middot; &lambda;=' + (cv.ridge_lambda || 8) + '</div>' +
        '<div class="card-sub">RMSE(ln) ' + (cv.cv_rmse_ln !== undefined ? cv.cv_rmse_ln.toFixed(2) : "n/a") + ' vs ' + (cv.baseline_rmse_ln !== undefined ? cv.baseline_rmse_ln.toFixed(2) : "n/a") + ' naive &middot; &beta;<sub>TVL</sub>=' + (cv.beta_tvl !== undefined ? cv.beta_tvl.toFixed(2) : "n/a") + '</div>' +
      '</div>' +
      '<div class="card">' +
        '<div class="card-k">Token Launch Odds Model</div>' +
        '<div class="card-v">Brier <span class="hl-cyan">' + (cv.odds_brier !== undefined ? cv.odds_brier.toFixed(3) : "n/a") + '</span> &middot; ' + (stats.global_multiple !== undefined ? stats.global_multiple.toFixed(2) + "x" : "n/a") + '</div>' +
        '<div class="card-sub">Logistic peer launch rate &middot; &beta;<sub>age</sub>=' + (cv.beta_age !== undefined ? cv.beta_age.toFixed(2) : "n/a") + ' &middot; &beta;<sub>7d</sub>=' + (cv.beta_growth !== undefined ? cv.beta_growth.toFixed(2) : "n/a") + '</div>' +
      '</div>' +
      '<div class="card">' +
        '<div class="card-k">Radar Economics</div>' +
        '<div class="card-v"><span class="hl-amber">' + fmtUsd(totalImplied) + '</span> total EV</div>' +
        '<div class="card-sub">Watchlist ' + (stats.watchlist_covered || 0) + '/' + (stats.watchlist || 0) + ' + ' + (stats.below_floor_rows || 0) + ' early &middot; median gas ~$' + (stats.median_farm_cost_usd || 15) + '</div>' +
      '</div>';
  }

  function buildFilters() {
    var cats = {};
    var chains = {};
    rows.forEach(function (r) {
      var c = r.category || "Uncategorized";
      cats[c] = (cats[c] || 0) + 1;
      (r.chains || []).forEach(function (ch) { chains[ch] = (chains[ch] || 0) + 1; });
    });
    $("cat").innerHTML = '<option value="all">All categories</option>' +
      Object.keys(cats).sort().map(function (c) {
        return '<option value="' + esc(c) + '">' + esc(c) + " (" + cats[c] + ")</option>";
      }).join("");
    $("chain").innerHTML = '<option value="all">All chains</option>' +
      Object.keys(chains).sort().map(function (c) {
        return '<option value="' + esc(c) + '">' + esc(c) + " (" + chains[c] + ")</option>";
      }).join("");
  }

  function filtered() {
    var q = state.q.trim().toLowerCase();
    var out = rows.filter(function (r) {
      if (state.segment === "watchlist" && !r.watchlist) return false;
      if (state.segment === "below" && r.watchlist) return false;
      if (state.verdict !== "all" && r.farm_verdict !== state.verdict) return false;
      if (state.cat !== "all" && (r.category || "Uncategorized") !== state.cat) return false;
      if (state.chain !== "all" && (r.chains || []).indexOf(state.chain) === -1) return false;
      if (q) {
        var hay = (r.name + " " + r.slug + " " + (r.category || "") + " " + (r.chains || []).join(" ")).toLowerCase();
        if (hay.indexOf(q) === -1) return false;
      }
      return true;
    });
    var k = state.sort;
    out.sort(function (a, b) {
      if (k === "implied") return b.implied_value_usd - a.implied_value_usd;
      if (k === "conditional") return b.conditional_value_usd - a.conditional_value_usd;
      if (k === "tvl") return b.tvl_usd - a.tvl_usd;
      if (k === "growth") return (b.change_7d === null ? -999 : b.change_7d) - (a.change_7d === null ? -999 : a.change_7d);
      if (k === "odds") return b.token_odds - a.token_odds;
      if (k === "age") return (b.age_days === null ? -1 : b.age_days) - (a.age_days === null ? -1 : a.age_days);
      if (k === "name") return a.name < b.name ? -1 : 1;
      if (k === "category") return (a.category || "") < (b.category || "") ? -1 : 1;
      return a.rank - b.rank;
    });
    return out;
  }

  function renderScatter(list) {
    var host = $("scatter");
    if (!list.length) {
      host.innerHTML = '<p class="muted">No protocols match current filters.</p>';
      return;
    }
    var W = 760, H = 148, padL = 52, padR = 16, padT = 12, padB = 22;
    var xs = list.map(function (r) { return Math.log10(Math.max(1, r.tvl_usd)); });
    var ys = list.map(function (r) { return Math.log10(Math.max(1, r.implied_value_usd)); });
    var xMin = Math.floor(Math.min.apply(null, xs) * 2) / 2;
    var xMax = Math.ceil(Math.max.apply(null, xs) * 2) / 2;
    var yMin = Math.floor(Math.min.apply(null, ys) * 2) / 2;
    var yMax = Math.ceil(Math.max.apply(null, ys) * 2) / 2;
    if (xMax <= xMin) xMax = xMin + 1;
    if (yMax <= yMin) yMax = yMin + 1;

    function sx(v) { return padL + ((v - xMin) / (xMax - xMin)) * (W - padL - padR); }
    function sy(v) { return H - padB - ((v - yMin) / (yMax - yMin)) * (H - padT - padB); }

    var grid = "";
    for (var gy = Math.ceil(yMin); gy <= Math.floor(yMax); gy++) {
      var py = sy(gy).toFixed(1);
      grid += '<line x1="' + padL + '" y1="' + py + '" x2="' + (W - padR) + '" y2="' + py + '" stroke="#19243a" stroke-width="1"/>';
      grid += '<text x="' + (padL - 6) + '" y="' + (+py + 3) + '" fill="#7e91ae" font-size="9" text-anchor="end">' + fmtUsd(Math.pow(10, gy)) + '</text>';
    }
    for (var gx = Math.ceil(xMin); gx <= Math.floor(xMax); gx++) {
      var px = sx(gx).toFixed(1);
      grid += '<line x1="' + px + '" y1="' + padT + '" x2="' + px + '" y2="' + (H - padB) + '" stroke="#19243a" stroke-width="1"/>';
      grid += '<text x="' + px + '" y="' + (H - 6) + '" fill="#7e91ae" font-size="9" text-anchor="middle">' + fmtUsd(Math.pow(10, gx)) + '</text>';
    }

    var dots = list.map(function (r) {
      var cx = sx(Math.log10(Math.max(1, r.tvl_usd))).toFixed(1);
      var cy = sy(Math.log10(Math.max(1, r.implied_value_usd))).toFixed(1);
      var active = r.slug === state.activeSlug;
      var fill = r.watchlist ? "#22d3ee" : "#34d399";
      var rad = active ? "6.2" : (r.watchlist ? "4.0" : "3.1");
      var stroke = active ? '#ffffff' : '#080c14';
      var sw = active ? "1.8" : "0.8";
      return '<circle data-slug="' + esc(r.slug) + '" cx="' + cx + '" cy="' + cy + '" r="' + rad + '" fill="' + fill + '" fill-opacity="' + (active ? "1" : "0.82") + '" stroke="' + stroke + '" stroke-width="' + sw + '" style="cursor:pointer"><title>#' + r.rank + ' ' + esc(r.name) + ' | TVL ' + fmtUsd(r.tvl_usd) + ' | Implied ' + fmtUsd(r.implied_value_usd) + '</title></circle>';
    }).join("");

    host.innerHTML = '<svg viewBox="0 0 ' + W + ' ' + H + '" role="img" aria-label="TVL vs implied launch value chart">' + grid + dots + '</svg>';
    var circles = host.querySelectorAll("circle[data-slug]");
    for (var i = 0; i < circles.length; i++) {
      circles[i].addEventListener("click", function () { select(this.getAttribute("data-slug")); });
    }
  }

  function renderBoard() {
    var list = filtered();
    $("count").textContent = "Showing " + list.length + " of " + rows.length;
    renderScatter(list);

    var html = "";
    list.forEach(function (r) {
      var active = r.slug === state.activeSlug ? ' class="active"' : "";
      var seg = r.watchlist
        ? '<span class="badge b-watch">watch</span>'
        : '<span class="badge b-below">early</span>';
      var ch = (r.chains || []).slice(0, 2).join(", ") + ((r.chains || []).length > 2 ? " +" + (r.chains.length - 2) : "");
      var oddsPct = Math.round(r.token_odds * 100);
      html += "<tr" + active + ' data-slug="' + esc(r.slug) + '">' +
        '<td class="rank num">' + r.rank + "</td>" +
        '<td><span class="pname">' + esc(r.name) + "</span> " + seg +
        '<span class="pslug">' + esc(r.slug) + " &middot; " + esc(ch || "n/a") + "</span></td>" +
        "<td>" + esc(r.category || "Uncategorized") + "</td>" +
        '<td class="num">' + fmtUsd(r.tvl_usd) + "</td>" +
        '<td class="num ' + growthCls(r.change_7d) + '">' + fmtPct(r.change_7d) + "</td>" +
        '<td class="num">' + fmtAge(r.age_days) + "</td>" +
        '<td class="num">' + fmtUsd(r.conditional_value_usd) + "</td>" +
        '<td class="num"><div class="odds-wrap"><div class="odds-bar"><div class="odds-fill" style="width:' + oddsPct + '%"></div></div>' + r.token_odds.toFixed(2) + "</div></td>" +
        '<td class="num implied">' + fmtUsd(r.implied_value_usd) + "</td>" +
        "<td>" + verdictBadge(r.farm_verdict) + "</td>" +
        "</tr>";
    });
    $("rows").innerHTML = html;

    var trs = $("rows").querySelectorAll("tr");
    for (var i = 0; i < trs.length; i++) {
      trs[i].addEventListener("click", function () {
        select(this.getAttribute("data-slug"));
      });
    }
  }

  function select(slug) {
    state.activeSlug = slug;
    var r = null;
    for (var i = 0; i < rows.length; i++) if (rows[i].slug === slug) { r = rows[i]; break; }
    if (!r) return;

    $("dName").textContent = "#" + r.rank + " " + r.name;
    $("dSub").textContent = r.slug + " · " + (r.chains || []).join(", ");
    $("dBadges").innerHTML = (r.watchlist
      ? '<span class="badge b-watch">Watchlist</span> '
      : '<span class="badge b-below">Below Floor</span> ') + verdictBadge(r.farm_verdict);

    var dec = r.decomposition || {};
    var compsHtml = (r.comps || []).map(function (c) {
      return "<tr><td>" + esc(c.name) + '</td><td class="num">' + fmtUsd(c.tvl_usd) +
        '</td><td class="num">' + fmtUsd(c.mcap_usd) + '</td><td class="num">' + c.multiple.toFixed(2) + "x</td></tr>";
    }).join("") || '<tr><td colspan="4" class="muted">Global fallback peers</td></tr>';

    var stepsHtml = (r.farm_steps || []).map(function (s) {
      return "<li>" + esc(s) + "</li>";
    }).join("");

    $("dBody").innerHTML =
      '<div class="kv">' +
        '<div><div class="k">Expected Launch Value</div><div class="v hl-cyan">' + fmtUsd(r.implied_value_usd) + "</div></div>" +
        '<div><div class="k">Conditional Launch Cap</div><div class="v">' + fmtUsd(r.conditional_value_usd) + "</div></div>" +
        '<div><div class="k">Token Odds</div><div class="v hl-green">' + (r.token_odds * 100).toFixed(1) + "%</div></div>" +
        '<div><div class="k">TVL / 7d / Age</div><div class="v">' + fmtUsd(r.tvl_usd) + ' <span class="' + growthCls(r.change_7d) + '">(' + fmtPct(r.change_7d) + ')</span> &middot; ' + fmtAge(r.age_days) + "</div></div>" +
      "</div>" +
      '<div class="section-title">Fitted Model Decomposition</div>' +
      '<div class="decomp">' +
        '<div><div class="dk">TVL Base</div><div class="dv">' + fmtUsd(dec.tvl_base_usd) + "</div></div>" +
        '<div><div class="dk">7d Growth</div><div class="dv">' + fmtMult(dec.growth_mult) + "</div></div>" +
        '<div><div class="dk">Age</div><div class="dv">' + fmtMult(dec.age_mult) + "</div></div>" +
        '<div><div class="dk">Chains</div><div class="dv">' + fmtMult(dec.chain_mult) + "</div></div>" +
        '<div><div class="dk">Cat Comps</div><div class="dv">' + fmtMult(dec.category_mult) + "</div></div>" +
      "</div>" +
      '<div class="section-title">Nearest Token-Trading Peers (' + esc(r.category || "Uncategorized") + ")</div>" +
      '<table class="comp-table"><thead><tr><th>Peer</th><th>TVL</th><th>Mcap</th><th>Mcap/TVL</th></tr></thead><tbody>' + compsHtml + "</tbody></table>" +
      '<div class="section-title">Costed Farm Playbook</div>' +
      '<div class="econ-bar">' +
        '<div>Est. Gas + Fees<strong>~$' + (r.farm_cost_usd || 15) + "</strong></div>" +
        '<div>Capital Band<strong>' + esc(r.farm_capital_usd || "$300-$1,000") + "</strong></div>" +
        '<div>Setup + Weekly<strong>~' + (r.farm_minutes || 35) + " min</strong></div>" +
      "</div>" +
      '<ol class="steps">' + stepsHtml + "</ol>";

    var trs = $("rows").querySelectorAll("tr");
    for (var j = 0; j < trs.length; j++) {
      if (trs[j].getAttribute("data-slug") === slug) trs[j].classList.add("active");
      else trs[j].classList.remove("active");
    }
    renderScatter(filtered());
  }

  function bind() {
    $("q").addEventListener("input", function () { state.q = this.value; renderBoard(); });
    $("segment").addEventListener("change", function () { state.segment = this.value; renderBoard(); });
    $("cat").addEventListener("change", function () { state.cat = this.value; renderBoard(); });
    $("chain").addEventListener("change", function () { state.chain = this.value; renderBoard(); });
    $("verdict").addEventListener("change", function () { state.verdict = this.value; renderBoard(); });
    $("sort").addEventListener("change", function () { state.sort = this.value; renderBoard(); });
    $("resetBtn").addEventListener("click", function () {
      state.q = ""; state.segment = "all"; state.cat = "all";
      state.chain = "all"; state.verdict = "all"; state.sort = "rank";
      $("q").value = ""; $("segment").value = "all"; $("cat").value = "all";
      $("chain").value = "all"; $("verdict").value = "all"; $("sort").value = "rank";
      renderBoard();
    });
    var ths = document.querySelectorAll("#board th[data-sort]");
    for (var i = 0; i < ths.length; i++) {
      ths[i].addEventListener("click", function () {
        state.sort = this.getAttribute("data-sort");
        $("sort").value = state.sort;
        renderBoard();
      });
    }
  }

  renderTopMeta();
  renderStrip();
  buildFilters();
  renderBoard();
  bind();
  if (rows.length > 0) select(rows[0].slug);
})();
